<?php require_once __DIR__ . '/../includes/bootstrap.php';$u=require_login('employer');$p=database();$s=$p->prepare("SELECT COUNT(*) jobs,SUM(status='active') active,(SELECT COUNT(*) FROM applications a JOIN jobs j ON j.id=a.job_id WHERE j.employer_id=?) applicants FROM jobs WHERE employer_id=?");$s->execute([$u['id'],$u['id']]);$c=$s->fetch();page_header('Employer dashboard');?><h1>Employer dashboard</h1><section class="stats"><div class="stat"><strong><?=e($c['jobs']??0)?></strong>Jobs</div><div class="stat"><strong><?=e($c['active']??0)?></strong>Active jobs</div><div class="stat"><strong><?=e($c['applicants']??0)?></strong>Applicants</div></section><p><a class="button" href="jobs.php">Manage job postings</a> <a class="button secondary" href="create-job.php">Create job</a> <a class="button secondary" href="profile.php">Company profile</a></p><?php page_footer(); ?>